{"tool":"submit_job","args":{"source":"import fs from 'node:fs';
import path from 'node:path';

export async function gate({ referenceDir, submissionDir }) {
  try {
    const expectedRaw = fs.readFileSync(path.join(referenceDir, 'expected.json'), 'utf8');
    const expected = JSON.parse(expectedRaw);

    const answerRaw = fs.readFileSync(path.join(submissionDir, 'answer.json'), 'utf8');
    const answer = JSON.parse(answerRaw);

    if (!answer || typeof answer !== 'object') {
      return { accept: false, reason: 'Answer is not an object' };
    }

    const requiredFields = ['invoice_number', 'vendor', 'total_amount', 'currency', 'due_date'];

    for (const field of requiredFields) {
      if (answer[field] === undefined) {
        return { accept: false, reason: `Missing required field: ${field}` };
      }

      let expVal = expected[field];
      let ansVal = answer[field];

      if (typeof expVal === 'string') expVal = expVal.trim();
      if (typeof ansVal === 'string') ansVal = ansVal.trim();

      if (field === 'total_amount') {
        const expNum = Number(expVal);
        const ansNum = Number(ansVal);
        if (!isNaN(expNum) && !isNaN(ansNum)) {
          if (expNum !== ansNum) {
            return { accept: false, reason: `Mismatch in ${field}` };
          }
          continue;
        }
      }

      if (String(expVal) !== String(ansVal)) {
        return { accept: false, reason: `Mismatch in ${field}` };
      }
    }

    return { accept: true, reason: 'Success' };
  } catch (e) {
    return { accept: false, reason: e.message };
  }
}"}}
